// Extract content to check
const input = $input.first().json;
const content = input.content || input.text || input.draft_text || '';

// Define risky claim patterns
const riskyPatterns = [
  { pattern: /48\s*h(our)?s?\s*(sla|turnaround|delivery)/i, type: 'SLA_CLAIM', risk: 'high' },
  { pattern: /guarantee[ds]?/i, type: 'GUARANTEE', risk: 'high' },
  { pattern: /(100|hundred)\s*%/i, type: 'ABSOLUTE_CLAIM', risk: 'medium' },
  { pattern: /\bfree\b/i, type: 'FREE_CLAIM', risk: 'low' },
  { pattern: /(always|never|every\s*time)/i, type: 'ABSOLUTE_LANGUAGE', risk: 'medium' },
  { pattern: /(complian(t|ce)|gdpr|hipaa|soc\s*2)/i, type: 'COMPLIANCE_CLAIM', risk: 'high' },
  { pattern: /\d+x\s*(faster|better|more)/i, type: 'COMPARISON_CLAIM', risk: 'medium' },
  { pattern: /save[ds]?\s*(\$|\d+%)/i, type: 'SAVINGS_CLAIM', risk: 'medium' },
  { pattern: /roi\s*of\s*\d+/i, type: 'ROI_CLAIM', risk: 'high' },
  { pattern: /refund|money\s*back/i, type: 'REFUND_CLAIM', risk: 'medium' }
];

const foundClaims = [];

for (const { pattern, type, risk } of riskyPatterns) {
  const matches = content.match(pattern);
  if (matches) {
    foundClaims.push({
      type,
      risk,
      match: matches[0],
      context: content.substring(
        Math.max(0, content.indexOf(matches[0]) - 50),
        Math.min(content.length, content.indexOf(matches[0]) + matches[0].length + 50)
      )
    });
  }
}

const hasHighRisk = foundClaims.some(c => c.risk === 'high');
const hasMediumRisk = foundClaims.some(c => c.risk === 'medium');

return {
  json: {
    content_id: input.content_id || 'manual',
    claims_found: foundClaims,
    claim_count: foundClaims.length,
    has_high_risk: hasHighRisk,
    has_medium_risk: hasMediumRisk,
    is_safe: foundClaims.length === 0,
    needs_review: hasHighRisk || hasMediumRisk
  }
};

